style.css:
/* Fondo azul clarito estilo ChatGPT */
body {
    background-color: #cce7ff !important; /* azul clarito */
    color: #003366 !important; /* texto azul oscuro para contraste */
    font-family: 'Arial', sans-serif; /* opcional, para que se vea limpio */
}

/* Opcional: poner bordes suaves a todo */
* {
    border-radius: 5px;
}

/* Opcional: suavizar las transiciones al cambiar colores */
* {
    transition: all 0.3s ease;
}
